export const strategyPortLabel=(node,port,graph=null)=>node.type==='REGIME_ROUTER'&&port.startsWith('case:')&&graph?(graph.nodes.find(n=>n.id===graph.edges.find(e=>e.to.nodeId===node.id&&e.to.port==='choices')?.from.nodeId)?.config.items?.find(v=>v.id===port.slice(5))?.label||port.slice(5)):isParameterPort(port)?parameterSpec(node,port)?.label??port:['SESSION_RULE','SESSION_TREND','SESSION_SIGNAL'].includes(node.type)&&port==='state'?'운용 상태':node.type==='MODEL'&&node.config.family==='HOURLY_VALUE_FOREST'&&port==='state'?'종목 시세·자기 계좌·재평가':node.type==='MODEL'&&port==='features'?'호가 특징':node.type==='MODEL'&&port==='position'?'자기 포지션':port.startsWith('case:')?(node.config.cases?.find(item=>item.id===port.slice(5))?.label||port.slice(5)):(portLabels[port]||port);
export function strategyPortTypeLabel(graph,nodeId,portId,direction='inputs'){
 const node=graph?.nodes?.find(item=>item.id===nodeId),spec=node&&decisionNodePortContract(node)[direction]?.find(port=>port.id===portId);if(!spec)return '자료형 확인 필요';
 const connected=direction==='inputs'?(graph.edges??[]).filter(edge=>edge.to.nodeId===nodeId&&edge.to.port===portId).map(edge=>{const source=graph.nodes.find(item=>item.id===edge.from.nodeId);return source&&decisionNodePortContract(source).outputs.find(port=>port.id===edge.from.port)?.dataType;}).filter(Boolean):[];
 const types=connected.length?connected:direction==='inputs'&&spec.accepts?.length?spec.accepts:[spec.dataType];return [...new Set(types)].map(type=>DECISION_PORT_TYPE_LABELS[type]??type).join(' / ');
}

