export function strategyNodeFocus(node,visual){return {x:node.position.x+(node.measured?.width??node.width??visual.nodeWidth)/2,y:node.position.y+visual.controlNodeHeight/2,options:{zoom:visual.focusZoom,duration:visual.fitDuration}};}
export function strategySelectionViewport(graph,id,visual){if(!graph.nodes.some(node=>node.id===id))return null;const ids=new Set([id]);for(const edge of graph.edges){if(edge.to.nodeId===id)ids.add(edge.from.nodeId);if(edge.from.nodeId===id)ids.add(edge.to.nodeId);}return {nodes:graph.nodes.filter(node=>ids.has(node.id)).map(node=>({id:node.id})),padding:visual.fitPadding,minZoom:visual.minZoom,maxZoom:visual.focusZoom,duration:visual.fitDuration};}
