export function strategyQuestionRouter(graph,node,{id='router-'+crypto.randomUUID().slice(0,8),position}={}){if(node.type!=='JEV_QUESTION'||node.config.question.type!=='choice')throw new Error('선택지 질문을 선택하세요.');const next=clone(graph),router=createDecisionStrategyNode('DECISION_ROUTER',{id,position:position||{x:node.position.x,y:node.position.y},config:{mode:'CHOICE',...(graph.nodes.some(n=>n.type==='ORDER'&&n.config.sizing==='SESSION_ORDERS')?{payload:'ORDER_PLAN'}:graph.nodes.some(n=>n.type==='ORDER'&&n.config.sizing==='TARGET_WEIGHTS')?{payload:'TARGET_WEIGHTS'}:{}),cases:node.config.question.candidates.map(({id,label})=>({id,label:label||id}))}});next.nodes.push(router);return connectStrategyNodes(next,{from:node.id,fromPort:'value',to:id,toPort:'selector'});}
