export function strategyOutputPhase(execution){const output=execution?.row?.output;if(['error','blocked','unknown'].includes(execution?.state)||output?.riskAllowed===false)return 'attention';if(['waiting','queued'].includes(execution?.state))return 'observing';if(!output?.ready)return 'idle';if(output.orderAllowed&&output.decision?.stance==='clutch')return 'clutch';if(output.orderAllowed||output.decision?.targetWeight>0)return 'investing';return 'idle';}
