export function strategyQuantTargetMode(node,mode){const config={...node.config,targetMode:mode};if(mode==='WEIGHT_DELTA'){delete config.sellPositionFraction;delete config.sellTargetQuantity;config.buyWeightDelta??=.1;config.sellWeightDelta??=.1;}else{delete config.buyWeightDelta;delete config.sellWeightDelta;}return config;}
