 if(action.type==='redo'){if(!history.future.length)return history;return {current:copy(history.future[0]),past:[...history.past.slice(-39),copy(history.current)],future:history.future.slice(1)};}
 if(action.type==='preview')return {...history,current:copy(action.snapshot)};
 if(action.type==='commitPreview'){const before=copy(action.before);return same(before,history.current)?history:{...history,past:[...history.past.slice(-39),before],future:[]};}
 if(action.type==='edit'){const next=copy(action.snapshot);return same(next,history.current)?history:{current:next,past:[...history.past.slice(-39),copy(history.current)],future:[]};}
