 return {schemaVersion:1,current,past:history.past.slice(-40).map(copy),future:history.future.slice(0,40).map(copy),view:{paletteOpen:view.paletteOpen===true,paletteView:view.paletteView==='add'?'add':'outline',paletteQuery:typeof view.paletteQuery==='string'?view.paletteQuery:'',selected:current.graph.nodes.some(node=>node.id===view.selected)||current.graph.compositions?.some(group=>group.id===view.selected)?view.selected:null,edgeId:current.graph.edges.some(edge=>edge.id===view.edgeId)?view.edgeId:null,preset:['QUANT','VIBE','MIXED','PORTFOLIO_QUANT','PORTFOLIO_JEV'].includes(view.preset)?view.preset:'QUANT'}};
