  if(saved?.schemaVersion!==1||!Array.isArray(saved.past)||!Array.isArray(saved.future)||saved.past.length>40||saved.future.length>40)return null;
  const snapshots=[saved.current,...saved.past,...saved.future];
  if(snapshots.some(value=>typeof value?.knowledge!=='boolean'||![1,2].includes(value.graph?.schemaVersion)||!Array.isArray(value.graph?.nodes)||!Array.isArray(value.graph?.edges)))return null;
