export function strategyNodeParameterKeys(node){return node.config.moduleId==='SMA_TREND'?['lookbackBars']:node.config.moduleId==='MOMENTUM'?['lookbackBars','scale']:node.config.moduleId==='MEAN_REVERSION'?['window','entryDeviation','exitDeviation']:node.config.moduleId==='BTC_DOC9'?['buyThreshold','sellThreshold','maWindow']:['shortWindow','longWindow','breakoutWindow','minOpportunity','baseWeightRatio','addProfitThreshold','trailingStopRatio','trendThreshold'];}
