 return {replayStepMs:numberToken('--graph-replay-step-ms',element),parameterNodeWidth:pixelToken('--graph-parameter-node-width',element),nodeWidth:pixelToken('--graph-node-width',element),nodeHeight:pixelToken('--graph-node-height',element),controlNodeHeight:pixelToken('--graph-node-control-height',element),layout:{originX:pixelToken('--graph-layout-origin-x',element),originY:pixelToken('--graph-layout-origin-y',element),rowStep:pixelToken('--graph-layout-row-step',element),columnStep:pixelToken('--graph-layout-column-step',element)},newSignalStep:pixelToken('--graph-new-signal-step',element),newProcessorX:pixelToken('--graph-new-processor-x',element),newProcessorStep:pixelToken('--graph-new-processor-step',element),arrowSize:pixelToken('--graph-arrow-size',element),backgroundGap:pixelToken('--graph-background-gap',element),backgroundDotSize:numberToken('--graph-background-dot-size',element),fitPadding:numberToken('--graph-fit-padding',element),fitDuration:numberToken('--graph-fit-duration',element),focusZoom:numberToken('--graph-focus-zoom',element),defaultZoom:numberToken('--graph-default-zoom',element),minZoom:numberToken('--graph-min-zoom',element),maxZoom:numberToken('--graph-max-zoom',element),gridColor:cssToken('--ds-chart-grid',element),minimapJev:cssToken('--graph-minimap-jev',element),minimapSignal:cssToken('--graph-minimap-signal',element),minimapProcessor:cssToken('--graph-minimap-processor',element)};
