export function mountStrategyGraphEditor(container,options){const visual=strategyGraphVisualTokens(container),root=createRoot(container);let current={...options};const controller={};const paint=()=>root.render(<Editor {...current} controller={controller} visual={visual}/>);paint();const cleanup=()=>root.unmount();cleanup.update=next=>{current={...current,...next};paint();};cleanup.getDraft=()=>controller.getDraft();cleanup.getHistory=()=>controller.getHistory?.()??null;cleanup.focusNode=id=>controller.focusNode(id);cleanup.fit=()=>controller.fit();return cleanup;}
